const ENDPOINTS = {
  US: 'https://api.newrelic.com/graphql',
  EU: 'https://api.eu.newrelic.com/graphql',
  JP: 'https://api.jp.newrelic.com/graphql',
};

const ENV_VARS = ['NEW_RELIC_API_KEY', 'NEW_RELIC_ACCOUNT_ID', 'NEW_RELIC_REGION'];

const DEFAULT_TIMEOUT_MS = 60_000;

export class UsageError extends Error {}
export class ApiError extends Error {}

// Reports which variables are set without ever exposing their values.
export function checkEnv(env = process.env) {
  return Object.fromEntries(ENV_VARS.map((name) => [name, env[name] ? 'set' : 'missing']));
}

// Sent on every request so New Relic-side request logs can tell skill-driven calls from UI or hand-written API calls.
// `client` is { skill, version } from the calling script.
const DEFAULT_USER_AGENT = 'newrelic-skills (workflow-automation)';
const userAgentFor = (client) => (client ? `newrelic-skills/${client.version} (workflow-automation/${client.skill})` : DEFAULT_USER_AGENT);

export function getConfig(env = process.env, client) {
  const apiKey = env.NEW_RELIC_API_KEY;
  if (!apiKey) {
    throw new UsageError(
      'NEW_RELIC_API_KEY is not set. Export a New Relic User API key in your shell before starting the agent.',
    );
  }
  const region = (env.NEW_RELIC_REGION || 'US').toUpperCase();
  if (!ENDPOINTS[region]) {
    throw new UsageError(`NEW_RELIC_REGION must be one of ${Object.keys(ENDPOINTS).join(', ')} (got "${region}").`);
  }
  return { apiKey, region, endpoint: ENDPOINTS[region], accountId: env.NEW_RELIC_ACCOUNT_ID || undefined, userAgent: userAgentFor(client) };
}

// Resolves the account id from an explicit flag value or the config default.
export function resolveAccountId(flagValue, config) {
  const raw = flagValue ?? config.accountId;
  if (raw === undefined || raw === '') {
    throw new UsageError('Account id required: pass --account <id> or set NEW_RELIC_ACCOUNT_ID.');
  }
  if (!/^\d+$/.test(String(raw))) {
    throw new UsageError(`Account id must be numeric (got "${raw}").`);
  }
  return Number(raw);
}

function redact(text, apiKey) {
  return apiKey ? String(text).split(apiKey).join('[REDACTED]') : String(text);
}

// Host only (no path or query string) of a redirect's Location header.
function locationHost(response, base) {
  const location = response.headers.get('location');
  if (!location) return 'an unspecified location';
  try {
    return new URL(location, base).host || 'an unspecified location';
  } catch {
    return 'an invalid location';
  }
}

// The timer covers the whole exchange, including reading the body: a server that sends headers and then stalls must not hang the caller.
export async function nerdgraph(query, variables, config, { fetchImpl = globalThis.fetch, timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await exchange(query, variables, config, fetchImpl, timeoutMs, controller.signal);
  } finally {
    clearTimeout(timer);
  }
}

async function exchange(query, variables, config, fetchImpl, timeoutMs, signal) {
  const failed = (err) => {
    const reason = err.name === 'AbortError' ? `timed out after ${timeoutMs} ms` : err.message;
    return new ApiError(redact(`NerdGraph request failed: ${reason}`, config.apiKey));
  };
  let response;
  try {
    response = await fetchImpl(config.endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'API-Key': config.apiKey, 'User-Agent': config.userAgent ?? DEFAULT_USER_AGENT },
      body: JSON.stringify({ query, variables }),
      // Never follow redirects: fetch would resend the API-Key header to whatever host the Location names.
      redirect: 'manual',
      signal,
    });
  } catch (err) {
    throw failed(err);
  }

  if (response.status >= 300 && response.status < 400) {
    throw new ApiError(redact(`NerdGraph returned HTTP ${response.status} redirecting to ${locationHost(response, config.endpoint)}; not following it, so the API key is not sent there. Check NEW_RELIC_REGION and any proxy between you and New Relic.`, config.apiKey));
  }
  if (response.status === 401 || response.status === 403) {
    throw new ApiError(
      `NerdGraph returned HTTP ${response.status}: User API key is invalid or lacks access to this account/region.`,
    );
  }
  let text;
  try {
    text = await response.text();
  } catch (err) {
    throw failed(err);
  }
  if (!response.ok) {
    throw new ApiError(redact(`NerdGraph returned HTTP ${response.status}: ${text.slice(0, 500)}`, config.apiKey));
  }

  let body;
  try {
    body = JSON.parse(text);
  } catch {
    throw new ApiError(redact(`NerdGraph returned non-JSON response: ${text.slice(0, 200)}`, config.apiKey));
  }
  if (body.errors?.length) {
    const messages = body.errors.map((e) => redact(e.message, config.apiKey));
    const err = new ApiError(`NerdGraph error: ${messages.join('; ')}`);
    // Lets callers tell GraphQL-level errors apart from transport/auth failures.
    err.graphqlErrors = messages;
    err.graphqlErrorClasses = body.errors.map((e) => e.extensions?.errorClass);
    throw err;
  }
  return body.data;
}
